    var p = Paginate(new List<string> { "a", "b", "c" }, 1, 2);
    Eq(p.Items, new[] { "a", "b" });
    Eq(p.TotalPages, 2);
});

Test("no items: zero pages and an empty page (boundary)", () =>
{
    var p = Paginate(new List<int>(), 1, 10);
    Eq(p.Items.Count, 0);
    Eq(p.TotalPages, 0);
    Eq(p.HasNext, false);
});

Test("a page past the end is empty", () =>
    Eq(Paginate(Enumerable.Range(1, 5).ToList(), 9, 10).Items.Count, 0));

Test("bad page or size throws ArgumentOutOfRangeException", () =>
{
    Throws<ArgumentOutOfRangeException>(() => Paginate(new List<int>(), 0, 10));
    Throws<ArgumentOutOfRangeException>(() => Paginate(new List<int>(), 1, 0));
    Throws<ArgumentOutOfRangeException>(() => Paginate(new List<int>(), 1, 101));
});

